    for (const shown of [false, true]) {
      const c = comp('VERTICAL', `Shown=${shown ? 'True' : 'False'}`); c.resize(320, 80); c.primaryAxisSizingMode = 'AUTO'; await bindNum(c, 'itemSpacing', 'space/8');
      c.appendChild(await text('Password', 'sm/SemiBold', 'text/2', 'Label'));
      const f = await field('field/bg', false, 320, 'space/6');
      const t = await text(shown ? 'YourPassword' : '••••••••••••', 'md/Regular', 'text/1', 'Text'); f.appendChild(t); fill(t);
      const eye = variantOf('IconButton', 'Size=sm, State=Default').createInstance(); eye.name = 'Toggle'; f.appendChild(eye); prop(eye, 'Icon', icon(shown ? 'EyeOff' : 'Eye').id);
      c.appendChild(f); fill(f); vs.push(c);
    }
    const set = figma.combineAsVariants(vs, page); set.name = 'PasswordField';
