      await bindNum(c, 'height', 'size/button-height'); await pad(c, null, filled ? 'space/6' : 'space/16', null, 'space/16'); await bindNum(c, 'itemSpacing', 'space/8');
      await radius(c, 'radius/pill'); c.fills = [await paint('field/bg')];
      c.appendChild(await iconInst('Search', 'text/2', 18, 'Icon'));
      const t = await text(filled ? 'sunset' : 'Search', 'md/Regular', filled ? 'text/1' : 'text/3', 'Text'); c.appendChild(t); fill(t);
      if (filled) { const clear = variantOf('IconButton', 'Size=xs, State=Default').createInstance(); clear.name = 'Clear'; prop(clear, 'Icon', icon('Close').id); c.appendChild(clear); }
