    await radius(ic, 'radius/md'); ic.fills = [await paint('accent/container')]; ic.appendChild(await iconInst('Download', 'accent/on-container', 18, 'Icon')); c.appendChild(ic);
    const col = auto('VERTICAL', 'Text'); await bindNum(col, 'itemSpacing', 'space/6'); c.appendChild(col); fill(col);
