    const b = await text('Pastel Studio 1.1 is downloaded. Restart to use it.', 'sm/Regular', 'text/2', 'Body'); col.appendChild(b); fill(b); b.textAutoResize = 'HEIGHT';
    const pb = variantOf('ProgressBar', 'Tone=Done, Size=md').createInstance(); col.appendChild(pb); fill(pb); pb.fills = [await paint('surface/4')];
    const acts = auto('HORIZONTAL', 'Actions'); acts.primaryAxisAlignItems = 'MAX'; await bindNum(acts, 'itemSpacing', 'space/8'); await bindNum(acts, 'paddingTop', 'space/6'); col.appendChild(acts); fill(acts);
    for (const [st, label] of [['Secondary', 'Later'], ['Primary', 'Restart']]) { const btn = variantOf('Button', `Style=${st}, Size=sm`).createInstance(); prop(btn, 'Label', label); acts.appendChild(btn); }
    t.componentPropertyReferences = { characters: c.addComponentProperty('Title', 'TEXT', 'Update ready') };
    b.componentPropertyReferences = { characters: c.addComponentProperty('Body', 'TEXT', b.characters) };
    c.description = 'A floating card about an update: surface/3, radius xl, elevation/overlay, an accent-container icon tile, the title md/Bold, a line in text/2, progress, then its actions.';
