      await bindNum(c, 'height', 'size/icon-button-size-sm'); await pad(c, null, 'space/10', null, 'space/10'); await bindNum(c, 'itemSpacing', 'space/6'); await radius(c, 'radius/md');
      if (bg) c.fills = [await paint(bg)];
